import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'

async function getDashboardData() {
  const res = await fetch('https://api.example.com/dashboard')
  return res.json()
}

export default async function Page() {
  const data = await getDashboardData()

  return (
    <main>
      <h1>Dashboard</h1>
      <CardStats
        totalRevenue={data.totalRevenue}
        totalInvoices={data.totalInvoices}
      />
      <RevenueChart revenue={data.revenue} />
      <LatestInvoices invoices={data.invoices} />
    </main>
  )
}

export default function Loading() {
  return (
    <div className="loading">
      <div className="spinner" />
      <p>Loading dashboard...</p>
    </div>
  )
}

import type { Metadata } from 'next'

export const metadata: Metadata = {
  title: 'Create Next App',
  description: 'Generated by create next app',
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}

export function LatestInvoices({
  invoices,
}: {
  invoices: { id: string; name: string; amount: number }[]
}) {
  return (
    <div className="invoices">
      <h2>Latest Invoices</h2>
      <ul>
        {invoices.map((invoice) => (
          <li key={invoice.id}>
            {invoice.name} - ${invoice.amount.toLocaleString()}
          </li>
        ))}
      </ul>
    </div>
  )
}

export function RevenueChart({
  revenue,
}: {
  revenue: { month: string; amount: number }[]
}) {
  return (
    <div className="chart">
      <h2>Revenue</h2>
      <ul>
        {revenue.map((item) => (
          <li key={item.month}>
            {item.month}: ${item.amount.toLocaleString()}
          </li>
        ))}
      </ul>
    </div>
  )
}

export function CardStats({
  totalRevenue,
  totalInvoices,
}: {
  totalRevenue: number
  totalInvoices: number
}) {
  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>${totalRevenue.toLocaleString()}</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p>{totalInvoices}</p>
      </div>
    </div>
  )
}

